effect.shader:
void main() {
    if (radius <= 0.0) { fragColor = texture(inputImg, acScreenNorm); return; }
    vec2 d = (acPass == 0) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
    vec2 passo = d * acTexelSize * (radius * acEscalaDePixel);

    vec4 soma = vec4(0.0);
    const int K = 9;
    for (int i = -4; i <= 4; i++) {
        vec2 uv = acScreenNorm + passo * float(i) / 4.0;
        soma += (acPass == 0) ? texture(inputImg, uv) : texture(hblur, uv);
    }
    fragColor = soma / float(K);
}
